/* El chip usa fondo oscuro y texto casi blanco: la paleta no tiene blanco puro,
   así que el texto del chip y del valor usan warm-cream (#FAF8F4). El label y
   el botón × usan los grises sobre fondo oscuro del propio sistema. */

.chipsRow {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: var(--bw-deep-steel);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-warm-cream);
  cursor: default;
}

.chipLabel {
  color: var(--bw-on-dark-dim);
  font-size: 11px;
  margin-right: 2px;
}

.chipValue {
  color: var(--bw-warm-cream);
}

.chipX {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--bw-on-dark-faint);
  font-size: 14px;
  line-height: 1;
  padding: 0 0 0 3px;
  display: flex;
  align-items: center;
  font-family: inherit;
  transition: color 0.12s;
}

.chipX:hover {
  color: var(--bw-danger-light);
}

.chipAdd {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: transparent;
  border: 1.5px dashed var(--bw-input-placeholder);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-steel-mist);
  cursor: pointer;
  font-family: inherit;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.chipAdd:hover {
  border-color: var(--bw-calibration-blue);
  color: var(--bw-calibration-blue);
}

.form {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.select,
.input {
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  padding: 6px 9px;
  font-size: 12px;
  color: var(--bw-deep-steel);
  background: var(--bw-warm-cream);
  font-family: inherit;
  outline: none;
  max-width: 180px;
  transition: border-color 0.15s;
}

.select:focus,
.input:focus {
  border-color: var(--bw-calibration-blue);
}

.submit {
  height: 30px;
  padding: 0 14px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius);
  color: var(--bw-warm-cream);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.submit:hover {
  opacity: 0.87;
}

