import { useState, type FormEvent } from 'react';
import {
  activeChips,
  withoutChip,
  ZONES,
  ZONE_LABELS,
  type ChipKey,
  type SearchCriteria,
  type Zone,
} from '../../lib/search';
import styles from './FilterChips.module.css';

/**
 * Los cinco filtros de la spec §3, en el orden fijo de su tabla de chips.
 * El `value` es una clave estable; no tiene por qué coincidir con la etiqueta.
 */
const FIELD_OPTIONS: { value: ChipKey; label: string }[] = [
  { value: 'partNumber', label: 'Ref' },
  { value: 'brand', label: 'Marca' },
  { value: 'minQuantity', label: 'Qty mín' },
  { value: 'zone', label: 'Zona' },
  { value: 'maxLeadTimeDays', label: 'Lead time máx' },
];

interface Props {
  criteria: SearchCriteria;
  onChange: (next: SearchCriteria) => void;
}

/**
 * Chips de filtro de SRCH-01.
 *
 * Presentacional y totalmente controlado: no guarda criterios, los recibe y
 * emite los nuevos enteros. El único estado propio es el del formulario
 * inline — si está abierto y qué hay tecleado en él.
 */
export function FilterChips({ criteria, onChange }: Props) {
  const [open, setOpen] = useState(false);
  const [field, setField] = useState<ChipKey>('partNumber');
  const [value, setValue] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const v = value.trim();
    if (!v) return;

    const next: SearchCriteria = { ...criteria };
    if (field === 'minQuantity') {
      const n = Number(v);
      if (!Number.isFinite(n)) return;
      next.minQuantity = n;
    } else if (field === 'maxLeadTimeDays') {
      const n = Number(v);
      if (!Number.isFinite(n)) return;
      next.maxLeadTimeDays = n;
    } else if (field === 'zone') {
      next.zone = v as Zone;
      next.country = '';
    } else if (field === 'partNumber') {
      next.partNumber = v;
    } else {
      next.brand = v;
    }

    onChange(next);
    setOpen(false);
    setValue('');
    setField('partNumber');
  };

  const valuePlaceholder =
    field === 'partNumber'
      ? '6205-2RS'
      : field === 'brand'
        ? 'SKF'
        : field === 'minQuantity'
          ? '500'
          : field === 'maxLeadTimeDays'
            ? '7'
            : '';

  return (
    <div className={styles.chipsRow}>
      {activeChips(criteria).map((chip) => (
        <div key={chip.key} className={styles.chip}>
          <span className={styles.chipLabel}>{chip.label}</span>
          <span className={styles.chipValue}>{chip.value}</span>
          <button
            type="button"
            className={styles.chipX}
            aria-label={`Quitar filtro ${chip.label}`}
            onClick={() => onChange(withoutChip(criteria, chip.key))}
          >
            ×
          </button>
        </div>
      ))}

      {/* El aria-label tapa el texto interno: sin él, el nombre accesible sería
          '+ Filtro' y los tests que buscan el botón por su papel no lo
          encontrarían. El visible sigue siendo '+ Filtro'. */}
      <button
        type="button"
        className={styles.chipAdd}
        aria-label="Añadir filtro"
        onClick={() => {
          setOpen((prev) => !prev);
          setValue('');
        }}
      >
        <i className="ti ti-plus" aria-hidden="true" />
        + Filtro
      </button>

      {open && (
        <form className={styles.form} onSubmit={handleSubmit}>
          <select
            className={styles.select}
            aria-label="Campo"
            value={field}
            onChange={(e) => {
              setField(e.target.value as ChipKey);
              setValue('');
            }}
          >
            {FIELD_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>

          {field === 'zone' ? (
            <select
              className={styles.select}
              aria-label="Valor"
              value={value}
              onChange={(e) => setValue(e.target.value)}
            >
              <option value="">—</option>
              {ZONES.map((zone) => (
                <option key={zone} value={zone}>
                  {ZONE_LABELS[zone]}
                </option>
              ))}
            </select>
          ) : (
            <input
              className={styles.input}
              aria-label="Valor"
              type={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 'number' : 'text'}
              min={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 0 : undefined}
              placeholder={valuePlaceholder}
              value={value}
              onChange={(e) => setValue(e.target.value)}
            />
          )}

          {/* Dos botones distintos: el que ABRE se llama 'Añadir filtro' y el
              que ENVÍA se llama 'Añadir'. Este no lleva aria-label. */}
          <button type="submit" className={styles.submit}>
            Añadir
          </button>
        </form>
      )}
    </div>
  );
}

