/* Sin token blanco puro en la paleta: los fondos de tabla, cabecera y el texto
   sobre azul usan warm-cream (#FAF8F4). El badge de marca del HTML aprobado usa
   #2D3748/#E2E8F0, que no existen como token; el par más cercano es
   deep-steel/vera-user-text. El tinte de fila consultada de la spec §3 es
   rgba(37,99,235,0.04); el token más cercano es row-hover-tint (0.025). El
   hover de fila del HTML (rgba(0,0,0,0.01)) se aproxima con hover-surface. */

.table {
  width: 100%;
  border-collapse: collapse;
  min-width: 860px;
}

.table th {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-brand);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-input-placeholder);
  padding: 10px;
  text-align: left;
  border-bottom: 1px solid var(--bw-divider-mist);
  white-space: nowrap;
  position: sticky;
  top: 0;
  background: var(--bw-warm-cream);
  z-index: 1;
}

.table th.thCheckbox {
  width: 36px;
  padding: 10px 8px 10px 14px;
}

.table th.thSortAsc,
.table th.thSortDesc {
  color: var(--bw-calibration-blue);
}

.table th.thSortAsc::after {
  content: ' ↑';
}

.table th.thSortDesc::after {
  content: ' ↓';
}

.sortButton {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  cursor: pointer;
  font-family: inherit;
}

.sortButton:hover {
  color: var(--bw-steel-mist);
}

.table td {
  padding: 10px;
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
}

.tdCheckbox {
  width: 36px;
  padding: 10px 8px 10px 14px;
}

.rowConsulted {
  background: var(--bw-row-hover-tint);
}

.rowHover:hover td {
  background: var(--bw-hover-surface);
}

.ref {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-deep-steel);
  white-space: nowrap;
}

.brandBadge {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-brand);
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  background: var(--bw-deep-steel);
  color: var(--bw-vera-user-text);
  font-weight: 500;
  letter-spacing: 0.03em;
  white-space: nowrap;
  display: inline-block;
}

.qtyOk {
  font-size: 13px;
  font-weight: 600;
  color: var(--bw-signal-green);
  white-space: nowrap;
}

.qtyLow {
  font-size: 13px;
  font-weight: 600;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.leadTime {
  font-size: 12px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.orgName {
  font-size: 13px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  background: var(--bw-cold-white);
  color: var(--bw-ink-steel);
  font-weight: 500;
  white-space: nowrap;
  border: 1px solid var(--bw-line-steel);
  display: inline-block;
}

.age {
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.ageStale {
  color: var(--bw-warning);
  font-weight: 500;
}

.favButton {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  color: var(--bw-brass);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  background: none;
  border: none;
  padding: 0;
  font-family: inherit;
  transition: opacity 0.12s;
}

.favButton:hover {
  opacity: 0.7;
}

.favStar {
  font-size: 14px;
  line-height: 1;
}

.actions {
  display: flex;
  gap: 5px;
  align-items: center;
}

.consultBtn {
  height: 28px;
  padding: 0 11px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 4px;
  color: var(--bw-warm-cream);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
  font-family: inherit;
  opacity: 0.32;
}

.contactBtn {
  height: 28px;
  padding: 0 11px;
  background: transparent;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  color: var(--bw-ink-steel);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
  font-family: inherit;
  opacity: 0.55;
}

.emptyCell {
  padding: 36px 16px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: 13px;
}

.checkbox {
  width: 15px;
  height: 15px;
  accent-color: var(--bw-calibration-blue);
  cursor: pointer;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

