import {
  ageLabel,
  ageLevel,
  countryName,
  daysSince,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

/**
 * Las nueve columnas con cabecera visible, sin la de checkbox. El orden es el
 * fijo e inamovible de la spec §7: se ordenan filas, nunca columnas.
 * `sortable: null` son Referencia, Empresa y Acciones.
 */
const COLUMNS: { label: string; sortable: SortColumn | null }[] = [
  { label: 'Referencia', sortable: null },
  { label: 'Marca', sortable: 'brand' },
  { label: 'Cantidad', sortable: 'quantity' },
  { label: 'Plazo', sortable: 'leadTime' },
  { label: 'Empresa', sortable: null },
  { label: 'País', sortable: 'country' },
  { label: 'Antigüedad', sortable: 'age' },
  { label: 'Favoritos', sortable: 'favorites' },
  { label: 'Acciones', sortable: null },
];

interface Props {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  /** Avisa con el id de la ORGANIZACIÓN, no de la línea. */
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  /** Avisa con el id de la ORGANIZACIÓN, no de la línea. */
  onContact: (orgId: string) => void;
}

/**
 * Tabla de resultados de SRCH-01.
 *
 * Presentacional: pinta las filas EN EL ORDEN QUE LAS RECIBE — ordenar es de la
 * pantalla — y no carga datos. El estado vacío de la spec §6 vive aquí, dentro
 * de la propia `<table>`, porque "no hay filas" es un estado de la lista.
 */
export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now = new Date(),
  onSort,
  onToggleRow,
  onToggleFavorite,
  onConsult,
  onContact,
}: Props) {
  return (
    <table className={styles.table}>
      <thead>
        <tr>
          <th scope="col" className={styles.thCheckbox}>
            <span className={styles.srOnly}>Seleccionar</span>
          </th>
          {COLUMNS.map((column) => {
            const col = column.sortable;
            if (col === null) {
              return (
                <th key={column.label} scope="col">
                  {column.label}
                </th>
              );
            }
            const active = sort?.column === col;
            const ariaSort = active
              ? sort?.direction === 'asc'
                ? 'ascending'
                : 'descending'
              : undefined;
            const className = active
              ? sort?.direction === 'asc'
                ? styles.thSortAsc
                : styles.thSortDesc
              : undefined;
            return (
              <th key={column.label} scope="col" aria-sort={ariaSort} className={className}>
                <button type="button" className={styles.sortButton} onClick={() => onSort(col)}>
                  {column.label}
                </button>
              </th>
            );
          })}
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 ? (
          <tr>
            <td colSpan={10} className={styles.emptyCell}>
              No hemos encontrado stock con estos filtros.
            </td>
          </tr>
        ) : (
          rows.map((row) => {
            const days = daysSince(row.lastUploadAt, now);
            const level = ageLevel(days);
            const quantityOk = meetsMinQuantity(row.quantity, minQuantity);
            return (
              <tr
                key={row.id}
                className={row.consulted ? styles.rowConsulted : styles.rowHover}
              >
                <td className={styles.tdCheckbox}>
                  <input
                    type="checkbox"
                    className={styles.checkbox}
                    checked={selected.has(row.id)}
                    onChange={() => onToggleRow(row.id)}
                    aria-label={`Seleccionar ${row.partNumber}`}
                  />
                </td>
                <td>
                  <span className={styles.ref}>{row.partNumber}</span>
                </td>
                <td>
                  <span className={styles.brandBadge}>{row.brand}</span>
                </td>
                <td>
                  <span className={quantityOk ? styles.qtyOk : styles.qtyLow}>
                    {quantityLabel(row.quantity)}
                  </span>
                </td>
                <td>
                  <span className={styles.leadTime}>{leadTimeLabel(row.leadTimeDays)}</span>
                </td>
                <td>
                  <span className={styles.orgName}>{row.orgName}</span>
                </td>
                <td>
                  <span className={styles.countryBadge}>{countryName(row.country)}</span>
                </td>
                <td>
                  <span className={`${styles.age} ${level !== 'fresh' ? styles.ageStale : ''}`}>
                    {ageLabel(days)}
                  </span>
                </td>
                <td>
                  <button
                    type="button"
                    className={styles.favButton}
                    aria-pressed={row.isFavorite}
                    aria-label={`${row.isFavorite ? 'Quitar de favoritos' : 'Añadir a favoritos'} ${row.orgName}`}
                    onClick={() => onToggleFavorite(row.orgId)}
                  >
                    <span className={styles.favStar} aria-hidden="true">
                      ★
                    </span>
                    <span>{row.favoriteCount}</span>
                  </button>
                </td>
                <td>
                  <div className={styles.actions}>
                    {/* F-100: los dos botones van apagados y dicen por qué. Los
                        callbacks se conservan: un botón disabled no los dispara,
                        y son el contrato para cuando exista FL-MSG-01. */}
                    <button
                      type="button"
                      className={styles.consultBtn}
                      disabled
                      title={
                        row.consulted
                          ? 'Ya consultada anteriormente'
                          : 'La consulta de una sola línea llega en la próxima versión. Marca la fila y usa «Consultar seleccionados».'
                      }
                      onClick={() => onConsult(row.id)}
                    >
                      Consultar
                    </button>
                    <button
                      type="button"
                      className={styles.contactBtn}
                      disabled
                      title="El hilo libre con el proveedor está fuera del alcance de esta versión"
                      onClick={() => onContact(row.orgId)}
                    >
                      Contactar
                    </button>
                  </div>
                </td>
              </tr>
            );
          })
        )}
      </tbody>
    </table>
  );
}

