/* Los tokens de la casa no tienen blanco puro: el más cercano es warm-cream
   (#FAF8F4), y se usa para el texto sobre acción primaria y los fondos de
   superficie blanca que el HTML aprobado pinta con `white`. */

.screen {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
  overflow-y: auto;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-brand);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 16px;
}

.resultsZone {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.metabar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.metaCount {
  font-size: 13px;
  color: var(--bw-steel-mist);
  flex: 1;
  min-width: 0;
}

.selectAll {
  background: none;
  border: none;
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-calibration-blue);
  cursor: pointer;
  padding: 0;
  white-space: nowrap;
  font-family: inherit;
  transition: opacity 0.12s;
}

.selectAll:hover {
  opacity: 0.7;
}

.consultButton {
  height: 32px;
  padding: 0 14px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  font-family: inherit;
  transition: opacity 0.12s;
}

.consultButton:disabled {
  opacity: 0.32;
  cursor: not-allowed;
}

.consultButton:not(:disabled):hover {
  opacity: 0.87;
}

/* El HTML aprobado usa rgba(184,146,74,0.4) de borde; el token más cercano es
   brass-border-strong (0.3). */
.watcherButton {
  height: 32px;
  padding: 0 14px;
  background: transparent;
  border: 1px solid var(--bw-brass-border-strong);
  border-radius: 5px;
  color: var(--bw-brass);
  font-size: 12px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 5px;
  font-family: inherit;
  opacity: 0.65;
}

.watcherButton i {
  font-size: 14px;
}

.cappedNotice {
  margin-bottom: 12px;
  padding: 8px 12px;
  border-radius: var(--bw-radius);
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning-dark);
  font-size: 12px;
  font-weight: 500;
}

.notice {
  margin-bottom: 12px;
  padding: 8px 12px;
  border-radius: var(--bw-radius);
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  color: var(--bw-primary-dark);
  font-size: 12px;
  font-weight: 500;
}

.tableWrap {
  flex: 1;
  min-height: 0;
  overflow: auto;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
