import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  EMPTY_CRITERIA,
  fetchResults,
  meetsMinQuantity,
  metaCounterLabel,
  nextSort,
  sortRows,
  toggleFavorite,
  type SearchCriteria,
  type SearchPage,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * F-118: firma pública — el shell la pasa desde App.tsx, cableado DESPUÉS de
   * escribirse esta tarea. El cableado VERA<->chips es del día 9 y sigue en
   * `out_of_scope`: se recibe y se ignora.
   */
  veraCriteria?: SearchCriteria | null;
}

/**
 * El aviso que sale al pulsar «Consultar seleccionados»: el destino (crear el
 * hilo) es la fila del día 10 del Plan §3 (GAP-004), y la pantalla no simula
 * ningún envío. El botón avisa por su callback — eso es el contrato de hoy.
 */
const CONSULT_PENDING_NOTICE = 'La creación del hilo de consulta llega en la próxima versión.';

/**
 * SRCH-01 · Panel de Resultados de Búsqueda.
 *
 * Es LA pantalla, no un componente de presentación: posee criterios, orden,
 * selección, carga y error, y ordena con `sortRows` antes de pasar las filas a
 * la tabla. El ordenar aquí y no en la tabla es el reparto del contrato: la
 * tabla pinta las filas EN EL ORDEN QUE LAS RECIBE.
 */
export function SearchResults({ profile, now, veraCriteria }: Props) {
  // La prop se declara por la firma pública y no se usa. El cableado
  // VERA<->chips es la fila del día 9 del Plan §3 (out_of_scope).
  void veraCriteria;

  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [page, setPage] = useState<SearchPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria })
      .then((p) => {
        if (cancelled) return;
        setPage(p);
        setLoading(false);
      })
      .catch(() => {
        if (cancelled) return;
        setError('No se pudieron cargar los resultados. Inténtalo de nuevo.');
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [criteria, profile.orgId, profile.id, retry]);

  const sortedRows = page ? sortRows(page.rows, sort) : [];
  const withStock = page
    ? page.rows.filter((row) => meetsMinQuantity(row.quantity, criteria.minQuantity)).length
    : 0;
  const allSelected = sortedRows.length > 0 && sortedRows.every((row) => selected.has(row.id));

  const handleCriteriaChange = (next: SearchCriteria) => {
    setCriteria(next);
    setLoading(true);
    setNotice(null);
  };

  const handleSort = (column: SortColumn) => {
    setSort(nextSort(sort, column));
  };

  const handleToggleRow = (lineId: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(lineId)) next.delete(lineId);
      else next.add(lineId);
      return next;
    });
  };

  const handleToggleSelectAll = () => {
    if (allSelected) setSelected(new Set());
    else setSelected(new Set(sortedRows.map((row) => row.id)));
  };

  const handleToggleFavorite = async (orgId: string) => {
    const row = page?.rows.find((r) => r.orgId === orgId);
    if (!row) return;
    try {
      await toggleFavorite(profile.id, orgId, !row.isFavorite);
      setLoading(true);
      setRetry((r) => r + 1);
    } catch {
      setError('No se pudieron cargar los resultados. Inténtalo de nuevo.');
    }
  };

  const handleConsultSelected = () => {
    if (selected.size === 0) return;
    setNotice(CONSULT_PENDING_NOTICE);
  };

  // F-100: los botones de fila van deshabilitados con su motivo. Estos
  // callbacks se conservan porque son el contrato para cuando exista FL-MSG-01;
  // un botón deshabilitado no los dispara.
  const handleConsultRow = (lineId: string) => {
    void lineId;
  };

  const handleContact = (orgId: string) => {
    void orgId;
  };

  return (
    <div className={styles.screen}>
      <div className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</div>
      <h1 className={styles.title}>Resultados de búsqueda</h1>

      <FilterChips criteria={criteria} onChange={handleCriteriaChange} />

      <div className={styles.resultsZone} aria-busy={loading}>
        <div className={styles.metabar}>
          <div className={styles.metaCount}>
            {page
              ? metaCounterLabel(page.total, withStock, criteria.minQuantity)
              : 'Cargando…'}
          </div>
          <button type="button" className={styles.selectAll} onClick={handleToggleSelectAll}>
            {allSelected ? 'Deseleccionar todos' : 'Seleccionar todos'}
          </button>
          <button
            type="button"
            className={styles.consultButton}
            disabled={selected.size === 0}
            onClick={handleConsultSelected}
          >
            Consultar seleccionados
          </button>
          <button
            type="button"
            className={styles.watcherButton}
            disabled
            title="Los watchers llegan en la próxima versión"
          >
            <i className="ti ti-bell-plus" aria-hidden="true" />
            Crear watcher con estos criterios
          </button>
        </div>

        {notice && (
          <div className={styles.notice} role="status">
            {notice}
          </div>
        )}

        {page?.capped && (
          <div className={styles.cappedNotice} role="note">
            Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.
          </div>
        )}

        {error ? (
          <div className={styles.error} role="alert">
            <p>{error}</p>
            <button
              type="button"
              className={styles.retryButton}
              onClick={() => setRetry((r) => r + 1)}
            >
              Reintentar
            </button>
          </div>
        ) : (
          <div className={styles.tableWrap}>
            {loading ? (
              <div className={styles.loading}>
                <i className="ti ti-loader" aria-hidden="true" />
                Cargando resultados…
              </div>
            ) : (
              <ResultsTable
                rows={sortedRows}
                sort={sort}
                selected={selected}
                minQuantity={criteria.minQuantity}
                now={now}
                onSort={handleSort}
                onToggleRow={handleToggleRow}
                onToggleFavorite={handleToggleFavorite}
                onConsult={handleConsultRow}
                onContact={handleContact}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
}
